import { test, expect } from './fixtures.js';
import { agentTurns, doubledTurns, tapEvents } from './liveTurns.js';

// The opt-in live e2e (R12, docs/metrics/README.md): the real agent-client,
// the real server with its real key, the real Gemini Live API. The user's
// voice is a WAV played by Chromium's fake mic, one per project
// (playwright.config.js, generated by e2e/make-prompts.sh). The model is
// nondeterministic, so the timeouts are generous and nothing is retried: a
// failure is a data point for the pass rate in .metrics/live.json.
//
// Each test reads the agent-client's `ds:*` performance marks (liveSession.js)
// and attaches the durations; e2e/live-reporter.js collects them. Each also
// taps the Live socket (tapLive) for the agent's turns as Gemini sent them,
// so a doubled answer is counted (issue #29).

const LIVE_SOCKET = /^wss:\/\/generativelanguage\.googleapis\.com\//;

/**
 * @typedef {{ name: string, startTime: number, detail: { name?: string, success?: boolean, bytes?: number, kind?: string } | null }} Mark
 */

/** @param {import('@playwright/test').Page} page */
function card(page) {
  // The card's landmark, not the whole host: the toast and Radix's
  // announcer live in the shadow root too.
  const panel = page.locator('#ai-presenter-agent-host').getByRole('complementary', {
    name: 'AI presenter',
  });
  return {
    status: panel.getByRole('status'),
    /** @param {string} name */
    button: (name) => panel.getByRole('button', { name, exact: true }),
    userLines: panel.locator('li.transcript__entry[data-role="user"]'),
    agentLines: panel.locator('li.transcript__entry[data-role="agent"]'),
  };
}

/**
 * @param {import('@playwright/test').Page} page
 * @returns {Promise<Mark[]>}
 */
function readMarks(page) {
  return page.evaluate(() =>
    performance
      .getEntriesByType('mark')
      .filter((entry) => entry.name.startsWith('ds:'))
      .map((entry) => ({
        name: entry.name,
        startTime: entry.startTime,
        detail: /** @type {PerformanceMark} */ (entry).detail,
      })),
  );
}

/**
 * @param {import('@playwright/test').Page} page
 * @param {string} name
 */
async function markTime(page, name) {
  return (await readMarks(page)).find((entry) => entry.name === name)?.startTime;
}

/**
 * The durations this run is measured by, in ms (null when the mark never came).
 * @param {Mark[]} marks
 * @param {Extra} extra
 */
function summarize(marks, extra) {
  /** @param {string} name */
  const at = (name) => marks.find((entry) => entry.name === name)?.startTime;
  /**
   * @param {number | undefined} from
   * @param {number | undefined} to
   */
  const between = (from, to) =>
    from === undefined || to === undefined ? null : Math.round(to - from);
  const connectStart = at('ds:connect-start');
  const open = at('ds:open');
  const firstAudio = at('ds:first-audio');
  const tools = marks
    .filter((entry) => entry.name.startsWith('ds:tool-start:'))
    .map((start) => {
      const id = start.name.slice('ds:tool-start:'.length);
      const end = marks.find((entry) => entry.name === `ds:tool-end:${id}`);
      return {
        name: start.detail?.name ?? null,
        roundTripMs: end ? Math.round(end.startTime - start.startTime) : null,
        success: end?.detail?.success ?? null,
      };
    });
  /** @param {string} name */
  const sizes = (name) =>
    marks.filter((entry) => entry.name === name).map((entry) => entry.detail?.bytes ?? null);
  const { closedAt } = extra;
  const turns = agentTurns(extra.events ?? []);
  const doubles = doubledTurns(turns);
  return {
    connectToOpenMs: between(connectStart, open),
    connectToFirstAudioMs: between(connectStart, firstAudio),
    openToFirstAudioMs: between(open, firstAudio),
    tools,
    reconnectMs: between(closedAt, at('ds:reconnected')),
    keyframeBytes: sizes('ds:keyframe'),
    knowledgeBytes: sizes('ds:knowledge'),
    loopTrips: marks
      .filter((entry) => entry.name === 'ds:loop-trip')
      .map((entry) => entry.detail?.kind ?? null),
    // Knowledge sent again by a reconnect: what M9's resend costs per drop.
    knowledgeResentBytes:
      closedAt === undefined
        ? null
        : marks
            .filter((entry) => entry.name === 'ds:knowledge' && entry.startTime > closedAt)
            .reduce((sum, entry) => sum + (entry.detail?.bytes ?? 0), 0),
    agentTurns: turns,
    doubledTurns: doubles.length,
    doubles,
    // The socket's non-audio traffic, for reading what prompted a turn.
    events: (extra.events ?? []).map(({ t, socket, dir, kind, text, names }) =>
      [t, socket, dir, kind, text ?? names?.join(',') ?? ''].join(' '),
    ),
    ...(extra.reconnectAttempts === undefined
      ? {}
      : {
          reconnectAttempts: extra.reconnectAttempts,
          resumed: extra.resumed,
          recalledKnowledge: extra.recalledKnowledge,
        }),
  };
}

/**
 * @typedef {{ closedAt?: number, resumed?: boolean, reconnectAttempts?: number, recalledKnowledge?: boolean, events?: import('./liveTurns.js').TapEvent[] }} Extra
 */
/** @type {Extra} */
let extra = {};

/**
 * A pass-through to the real Gemini socket that records every non-audio
 * message both ways (liveTurns.js), and lets the reconnect scenario drop the
 * socket and read whether a reconnect's setup asked to resume. Nothing it
 * keeps holds the token: that is in the socket's URL, which isn't recorded.
 * @param {import('@playwright/test').Page} page
 */
async function tapLive(page) {
  /** @type {import('./liveTurns.js').TapEvent[]} */
  const events = [];
  /** @type {import('@playwright/test').WebSocketRoute[]} */
  const sockets = [];
  /** @type {boolean[]} */
  const resumedPerSocket = [];
  const started = Date.now();
  await page.routeWebSocket(LIVE_SOCKET, (ws) => {
    const server = ws.connectToServer();
    const index = sockets.push(ws) - 1;
    ws.onMessage((message) => {
      if (resumedPerSocket[index] === undefined) {
        const frame = JSON.parse(String(message));
        resumedPerSocket[index] = Boolean(frame.setup?.sessionResumption?.handle);
      }
      events.push(...tapEvents(message, 'out', index, Date.now() - started));
      server.send(message);
    });
    server.onMessage((message) => {
      events.push(...tapEvents(message, 'in', index, Date.now() - started));
      ws.send(message);
    });
  });
  extra.events = events;
  return { sockets, resumedPerSocket };
}

test.beforeEach(() => {
  extra = {};
});

// How long the agent is listened to once it has answered: a doubled answer
// (issue #29) comes after the turn that ends the task, which the assertions
// alone would cut off.
const SETTLE_MS = 10_000;

/**
 * Waits for the agent's turn that follows its last tool response to complete,
 * then listens SETTLE_MS more.
 * @param {import('@playwright/test').Page} page
 */
async function settle(page) {
  const answered = () => {
    const events = extra.events ?? [];
    const lastResponse = events.findLastIndex((event) => event.kind === 'toolResponse');
    return events.slice(lastResponse + 1).some((event) => event.kind === 'turnComplete');
  };
  await expect.poll(answered, { timeout: 30_000 }).toBe(true);
  await page.waitForTimeout(SETTLE_MS);
}

/**
 * The card's transcript, one line per turn as the card coalesces them
 * (transcript.js), so a failed run says what the agent heard and answered.
 * The card keeps the last 20 turns, so that is what a failure records.
 * @param {import('@playwright/test').Page} page
 */
async function readTranscript(page) {
  return page.locator('#ai-presenter-agent-host li.transcript__entry').evaluateAll((items) =>
    items.map((item) => {
      const role = item instanceof HTMLElement ? item.dataset.role : '';
      const text = item.querySelector('.transcript__text')?.textContent ?? '';
      return `${role}: ${text.replace(/\s+/g, ' ').trim()}`;
    }),
  );
}

// After every test, passed or not: a failed run's partial numbers still count,
// and it carries its transcript.
test.afterEach(async ({ page }, testInfo) => {
  const marks = await readMarks(page).catch(() => []);
  const failed = testInfo.status !== testInfo.expectedStatus;
  const transcript = failed ? await readTranscript(page).catch(() => []) : undefined;
  await testInfo.attach('live-metrics', {
    contentType: 'application/json',
    body: JSON.stringify({ ...summarize(marks, extra), transcript }),
  });
});

/**
 * Records each value the target app's counter shows, in order.
 * @param {import('@playwright/test').Page} page
 * @param {string[]} values
 */
async function watchCounter(page, values) {
  await page.exposeBinding('__e2eCounterChanged', (_source, /** @type {string} */ value) => {
    values.push(value);
  });
  // On window, once per window: an iframe's first document reuses the Window
  // of its initial about:blank, where the init script already ran (as in
  // fixtures.js), and a listener on that blank document would never fire.
  await page.addInitScript(() => {
    if (window.__e2eCounterWatched) return;
    window.__e2eCounterWatched = true;
    window.addEventListener('DOMContentLoaded', () => {
      const counter = document.querySelector('[data-testid="counter-value"]');
      if (!counter) return;
      new MutationObserver(() => window.__e2eCounterChanged(counter.textContent ?? '')).observe(
        counter,
        { childList: true, characterData: true, subtree: true },
      );
    });
  });
}

/** @param {import('@playwright/test').Page} page */
async function connectLive(page) {
  const { status, button } = card(page);
  const tap = await tapLive(page);
  await page.goto('/');
  await button('Talk to the AI Presenter').click();
  await expect(status).toHaveText('Live', { timeout: 15_000 });
  return tap;
}

test('greeting: the agent greets on connect', async ({ page }) => {
  test.setTimeout(60_000);
  await connectLive(page);

  await expect.poll(() => markTime(page, 'ds:first-audio'), { timeout: 20_000 }).toBeDefined();
  await expect(card(page).agentLines.first()).toBeVisible({ timeout: 20_000 });
  await settle(page);
});

test('task: the spoken six-step task drives the target app', async ({ page }) => {
  test.setTimeout(220_000);
  // The counter lives on Home only and resets on every load, so its values
  // are recorded as they change rather than read after the agent has left.
  /** @type {string[]} */
  const counterValues = [];
  await watchCounter(page, counterValues);
  const frame = page.frameLocator('#target-app-frame');

  await connectLive(page);

  // The last step first, with the most room; the rest must hold once it does.
  await expect(frame.getByTestId('save-confirmation')).toBeVisible({ timeout: 150_000 });
  await expect(frame.getByTestId('settings-heading')).toBeVisible();
  await expect(frame.getByTestId('notifications-toggle')).toBeChecked();
  await expect(frame.getByTestId('plan-select')).toHaveValue('pro');
  expect(counterValues, 'the counter was incremented exactly twice').toEqual(['1', '2']);
  await settle(page);
});

// Close to issue #29's report: one spoken request that makes the agent act,
// then its answer, listened to for a repeat.
test('act: a spoken request is carried out and answered once', async ({ page }) => {
  test.setTimeout(120_000);
  /** @type {string[]} */
  const counterValues = [];
  await watchCounter(page, counterValues);
  await connectLive(page);

  await expect.poll(() => counterValues.at(-1), { timeout: 60_000 }).toBe('3');
  await settle(page);
  expect(counterValues, 'the counter went to three, once').toEqual(['1', '2', '3']);
});

// Issue #22: the Orders page has 139 elements, so the agent sees the 30
// nearest the view (bridge.js). The third order is on screen when the page
// loads; the agent has to navigate there and tick that row, and only that one.
test('orders: a row on the dense Orders page is ticked', async ({ page }) => {
  test.setTimeout(120_000);
  const frame = page.frameLocator('#target-app-frame');
  await connectLive(page);

  await expect(frame.getByTestId('order-1003-select')).toBeChecked({ timeout: 60_000 });
  await settle(page);
  await expect(frame.getByTestId('orders-heading')).toBeVisible();
  await expect(frame.getByTestId('orders-selected-count')).toHaveText('1 selected');
});

// The reconnect scenario's knowledge file (knowledgeStore.js's storage format).
// The follow-up asks for the code name, so the answer says whether the resumed
// session still has the knowledge sent before the drop (M9).
const KNOWLEDGE_FILE = {
  id: 'e2e-knowledge',
  name: 'demo-notes.md',
  size: 0,
  addedAt: 0,
  text: [
    '# Demo notes',
    'The code name of this demo is Pelican.',
    'The demo app has three pages: Home, with a counter; Settings, with notifications,',
    'notes, a plan (Free, Pro or Team) and a Save button; and Orders, with a table of orders',
    'and a New order form. Saving the settings shows a confirmation.',
    'The Pro plan adds priority support and unlimited projects; the Team plan adds shared',
    'workspaces and single sign-on. Notifications are off by default.',
  ].join('\n'),
};

test('reconnect: a dropped socket recovers and the conversation carries on', async ({ page }) => {
  test.setTimeout(120_000);
  await page.addInitScript((file) => {
    if (window.top === window) {
      localStorage.setItem('ds-agent-knowledge-files', JSON.stringify([file]));
    }
  }, KNOWLEDGE_FILE);
  const { status, userLines, agentLines } = card(page);

  const { sockets, resumedPerSocket } = await connectLive(page);
  await expect.poll(() => markTime(page, 'ds:first-audio'), { timeout: 20_000 }).toBeDefined();

  // Watch for `Reconnecting` from inside the page before dropping the socket:
  // the window can be shorter than an assertion's polling interval.
  const sawReconnecting = page.waitForFunction(
    () =>
      document
        .querySelector('#ai-presenter-agent-host')
        ?.shadowRoot?.querySelector('[role="status"]')
        ?.textContent?.startsWith('Reconnecting'),
    undefined,
    { polling: 'raf', timeout: 10_000 },
  );
  extra.closedAt = await page.evaluate(() => performance.now());
  // Closing the page side; the server side follows (connectToServer's default).
  await sockets[0].close({ code: 1011, reason: 'e2e forced close' });
  await sawReconnecting;

  await expect(status).toHaveText('Live', { timeout: 15_000 });
  await expect.poll(() => markTime(page, 'ds:reconnected')).toBeDefined();
  // Usually one new socket. Gemini can refuse an immediate resume while it
  // still holds the dropped client; the backoff's next attempt resumes then.
  expect(sockets.length).toBeGreaterThanOrEqual(2);
  extra.reconnectAttempts = sockets.length - 1;
  extra.resumed = resumedPerSocket.at(-1);

  // The follow-up question is spoken ~12 s after Talk, after the drop: the
  // recovered session hears it and answers.
  const agentLinesBefore = await agentLines.count();
  await expect(userLines.first()).toBeVisible({ timeout: 45_000 });
  await expect
    .poll(() => agentLines.count(), { timeout: 45_000 })
    .toBeGreaterThan(agentLinesBefore);
  // Recorded, not asserted: a metric for M9, and the model's wording varies.
  // The answer streams in, so it gets a few seconds to name the code name.
  const answer = async () => (await agentLines.allTextContents()).slice(agentLinesBefore).join('');
  extra.recalledKnowledge = await expect
    .poll(answer, { timeout: 10_000 })
    .toMatch(/pelican/i)
    .then(
      () => true,
      () => false,
    );
});
